raw:
{
  "story": "Mitosis is the division of a cell genome into two identical daughter cells. DNA condenses into chromosomes, aligns at the metaphase plate, separates at sister chromatids, and reforms nuclei.",
  "aha": {
    "stateId": "anaphase",
    "observation": "Sister chromatids pull apart toward opposite poles as spindle fibers shorten."
  },
  "layout": {
    "preset": "stepper-vertical",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "reason": "variant.states.why"
      }
    },
    {
      "id": "ghost",
      "kind": "previous-state-ghost",
      "bind": {
        "regions": "previous.regions"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "variant.states.why",
        "target": "variant.states.calloutRegion",
        "text": "variant.states.sentence"
      }
    },
    {
      "id": "readouts",
      "kind": "value-readout",
      "bind": {
        "values": "variant.states.readouts"
      }
    },
    {
      "id": "bar",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.stepIndex"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Mitosis Phase",
      "options": [
        "Prophase",
        "Metaphase",
        "Anaphase",
        "Telophase"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Mitosis Cycle",
        "regions": [
          {
            "id": "chromosomes",
            "label": "Chromosomes",
            "kind": "dna",
            "values": ["Condensed", "Aligned", "Separated", "Decondensed"]
          },
          {
            "id": "spindle",
            "label": "Spindle Fibers",
            "kind": "protein",
            "values": ["Forming", "Attached", "Shortening", "Disassembling"]
          },
          {
            "id": "nucleus",
            "label": "Nuclear Membrane",
            "kind": "membrane",
            "values": ["Breaking Down", "Absent", "Absent", "Reforming"]
          }
        ],
        "states": [
          {
            "id": "prophase",
            "label": "Prophase",
            "short": "Condense",
            "sentence": "Chromatin condenses into visible sister chromatids and mitotic spindle forms.",
            "why": "DNA must be tightly packaged for safe segregation.",
            "active": ["chromosomes", "spindle", "nucleus"],
            "calloutRegion": "chromosomes",
            "readouts": [
              {
                "id": "chromosomes-count",
                "label": "Chromosomes",
                "value": "46 duplicated"
              },
              {
                "id": "ploidy",
                "label": "Ploidy",
                "value": "2n"
              }
            ]
          },
          {
            "id": "metaphase",
            "label": "Metaphase",
            "short": "Align",
            "sentence": "Chromosomes align precisely at the cell equator.",
            "why": "Ensures equal distribution to both daughter cells.",
            "active": ["chromosomes", "spindle"],
            "calloutRegion": "chromosomes",
            "readouts": [
              {
                "id": "chromosomes-count",
                "label": "Chromosomes",
                "value": "Aligned at plate"
              },
              {
                "id": "ploidy",
                "label": "Ploidy",
                "value": "2n"
              }
            ]
          },
          {
            "id": "anaphase",
            "label": "Anaphase",
            "short": "Separate",
            "sentence": "Sister chromatids are pulled apart to opposite poles.",
            "why": "Physical separation creates two identical sets of genetic material.",
            "active": ["chromosomes", "spindle"],
            "calloutRegion": "chromosomes",
            "readouts": [
              {
                "id": "chromosomes-count",
                "label": "Chromatids",
                "value": "92 moving"
              },
              {
                "id": "ploidy",
                "label": "Ploidy",
                "value": "Separating"
              }
            ]
          },
          {
            "id": "telophase",
            "label": "Telophase",
            "short": "Reform",
            "sentence": "Nuclear envelopes reform around each new set of chromosomes.",
            "why": "Restores normal nuclear compartmentalization before division completes.",
            "active": ["chromosomes", "nucleus"],
            "calloutRegion": "nucleus",
            "readouts": [
              {
                "id": "chromosomes-count",
                "label": "Chromosomes",
                "value": "46 per side"
              },
              {
                "id": "ploidy",
                "label": "Ploidy",
                "value": "2n each"
              }
            ]
          }
        ]
      }
    ]
  }
}
